class AntiAmplification {
  constructor() { this.recv = 0; this.sent = 0; this.validated = false; }
  onReceive(bytes) { this.recv += bytes; }
  validate() { this.validated = true; }
  canSend(n) {
    if (this.validated) return true;
    return this.sent + n <= this.recv;
  }
  send(n) { if (!this.canSend(n)) throw new Error('over budget'); this.sent += n; }
}

