const a = new AntiAmplification();
a.onReceive(1200);
const fits = a.canSend(3000) === true;
const blocked = a.canSend(4000) === false;
a.sent = 3000;
const afterSend = a.canSend(700) === false;
a.validate();
const afterValidate = a.canSend(100000) === true;
const ok = fits && blocked && afterSend && afterValidate;
console.log(ok ? 'PASS' : 'FAIL fits=' + fits + ' blocked=' + blocked + ' afterSend=' + afterSend + ' afterValidate=' + afterValidate);

