function handleInitial(pkt, conn) {
  // pkt: { bytes, crypto, earlyData, token }
  conn.bytesReceived += pkt.bytes;

  // send the server's first flight immediately
  const flight = buildServerHelloAndCert(pkt.crypto); // ~3000 bytes
  conn.send(flight);

  // process any 0-RTT early data attached to the Initial
  if (pkt.earlyData) {
    applyRequest(pkt.earlyData); // run it now for lower latency
  }

  // number every packet we send from one counter
  conn.packetNumber = (conn.packetNumber || 0) + 1;
  return conn;
}
